import * as z from "zod";
import { ai, MODEL } from "../gemini";

export const VerdictSchema = z.object({
  verdict: z.enum(["approved", "rejected", "unsure"]),
  reason: z.string().min(1),
});
export type Verdict = z.infer<typeof VerdictSchema>;

type DareToCheck = {
  title: string;
  instructions: string;
  alternatives: { text: string }[];
  proof: string;
};

// Prompt generated by Claude
function buildPrompt(dare: DareToCheck) {
  return `You check photo proof for an outdoor dare in a friendly game.

Dare: ${dare.title}
Instructions: ${dare.instructions}
Equal alternatives (any of these also counts): ${dare.alternatives.map((a) => a.text).join(" | ")}
The photo should show: ${dare.proof}

Decide if the photo reasonably shows the dare (or one of its alternatives) was done.
- "approved": it clearly or plausibly matches. Be generous; this is for fun and encouragement.
- "rejected": it clearly shows something unrelated (e.g. a screenshot, a blank image, an indoor photo for an outdoor dare).
- "unsure": too dark, blurry or ambiguous to tell.
Give one short, kind sentence as the reason, speaking to the player.`;
}

export async function checkProof(
  dare: DareToCheck,
  image: { mimeType: string; base64: string },
) {
  try {
    const response = await ai.models.generateContent({
      model: MODEL,
      contents: [
        { inlineData: { mimeType: image.mimeType, data: image.base64 } },
        { text: buildPrompt(dare) },
      ],
      config: {
        responseMimeType: "application/json",
        responseJsonSchema: z.toJSONSchema(VerdictSchema),
      },
    });

    const result = VerdictSchema.safeParse(JSON.parse(response.text ?? ""));
    return result.success ? result.data : null;
  } catch (err) {
    console.warn("Photo check failed:", err);
    return null;
  }
}
